import {taxCodes} from 'webcommander-sdk';

const response = await taxCodes.listTaxCodes(client, {limit: 20});
for (const taxCode of response.map.tax_codes) {
    console.log(taxCode.id, taxCode.name, taxCode.rate);
}
console.log(response.map.pagination.total);

