create_tax_code.code:
import {taxCodes} from 'webcommander-sdk';

const taxCode = {
    name: 'LUXURY',
    label: 'Luxury goods',
    description: 'Higher rate for luxury goods',
    rate: 15.0,
    resolver_type: 'flat',
    priority: 1,
};
const response = await taxCodes.createTaxCode(client, {tax_code: taxCode});
console.log(response.map.tax_code.id);

